steps.prompt:
The product's specs:
{{brief}}

Write the product page and answer with JSON only: {"title": at most 70 characters, "bullets": 3 to 6 short benefits each backed by a spec, "description": 80 to 160 words, "meta_description": at most 155 characters}. Use only what the specs say. Write in the language of the specs.

steps.code:
const p = json(steps[1]);
if (!p || typeof p !== 'object') return 'CHECK:
- The copy did not come back as JSON, so it is shown as it is.

' + steps[1];
const warn = [];
const title = String(p.title || ''), meta = String(p.meta_description || ''), bullets = Array.isArray(p.bullets) ? p.bullets : [];
if (!title) warn.push('There is no title.');
if (title.length > 70) warn.push('The title has ' + title.length + ' characters; search results show about 60 to 70.');
if (meta.length > 155) warn.push('The meta description has ' + meta.length + ' characters; keep it to 155.');
if (bullets.length < 3 || bullets.length > 6) warn.push('There are ' + bullets.length + ' bullets; 3 to 6 read best.');
return (warn.length ? 'CHECK:
- ' + warn.join('
- ') + '

' : '') + 'TITLE
' + title + '

BULLETS
' + bullets.map(b => '- ' + b).join('
') + '

DESCRIPTION
' + (p.description || '') + '

META DESCRIPTION
' + meta;
